$if !talkedSitri {
    Morgan
    ---
    You're awake
    ---
    Have you forgotten the time?
    ---
    Get your fishing rod ready and begin fishing
    ---
    signal(set,talkedSitri,true)
    ?> Have you found the seal? -> useful
}
$else {
    $if givenFragment1 {
        -> puzzleChecker
    }
    $else {
    Throw, listen, wait, pull. A ritual, like everything else we do
    -> choices
    }
}

$if showRitualChoice {
    ?> I've found the correct fish for the ritual -> ritual
}
$else {
$if foundFragment1 {
    ?> I've found something -> fragment1
    }
}
$if replyFragment1 {
?> What do you make of Marbas? -> marbas
?> Do you ever sleep, Sitri? -> sleep
}
$else {
?> I've caught some fish -> caught
?> Could you remind me how to fish? -> remind
}
?> Leave

signal(>,refusalRep,1)
$if refusalRepbool {
    -> refusal ending
}

signal(>,inheritanceRep,1)
$if inheritanceRepbool {
    -> inheritance ending
}

-> neutral

signal(flipCoin)
$if flipCoin == "heads" {
-> inheritance ending
}
$else {
-> refusal ending
}

$if solvedFragment3 {
    -> solveFragment3
}

$if givenFragment3 {
    -> giveFragment3
}

$if solvedFragment2 {
    -> solveFragment2
}

$if givenFragment2 {
    -> giveFragment2
}

$if solvedFragment1 {
    -> solveFragment1
}

$if givenFragment1 {
    -> giveFragment1
}

$if !replySolvedFragment1 {
    It's the right species!
    ---
    We can continue the ritual
    ---
    Find the next fragment
    ---
    signal(set,replySolvedFragment1,true)
    }
    $else {
        Throw, listen, wait, pull. A ritual, like everything else we do
    -> choices
    }

$if !replySolvedFragment2 {
    It's the right species!
    ---
    We can continue the ritual
    ---
    Find the next fragment
    ---
    signal(set,replySolvedFragment2,true)
    }
    $else {
        Throw, listen, wait, pull. A ritual, like everything else we do
    -> choices
    }

$if !replySolvedFragment3 {
    This must be the last fragment
    ---
    It references vaimmus
    ---
    It's a type of fish that has a spectral body and is able to shift it's own eyes
    ---
    signal(set,replySolvedFragment3,true)
    }
    $else {
        Throw, listen, wait, pull. A ritual, like everything else we do
    -> choices
    }
